const items = $input.all();
const now   = new Date().toISOString();

// Extraire les résultats de chaque invariant
const inv1 = items[0]?.json || {};
const inv2 = items[1]?.json || {};
const inv3 = items[2]?.json || {};
const inv4 = items[3]?.json || {};
const vol  = items[4]?.json || {};

const echecs = [
  inv1.statut === 'ECHEC' ? `Nœuds isolés: ${inv1.total_iso}` : null,
  inv2.statut === 'ECHEC' ? `Matchs incomplets: ${inv2.matchs_incomplets}` : null,
  inv3.statut === 'ECHEC' ? `Stats invalides: ${inv3.stats_invalides}` : null,
  inv4.statut === 'ECHEC' ? `Contrats conflits: ${inv4.joueurs_conflits}` : null,
].filter(Boolean);

const statut_global = echecs.length === 0 ? 'SAIN' : 'DÉGRADÉ';

const rapport = {
  timestamp:      now,
  statut_global,
  echecs,
  invariants: {
    noeuds_isoles:    { statut: inv1.statut, details: inv1 },
    matchs_incomplets:{ statut: inv2.statut, details: inv2 },
    stats_invalides:  { statut: inv3.statut, details: inv3 },
    contrats_actifs:  { statut: inv4.statut, details: inv4 },
  },
  volumes: {
    joueurs:      vol.nb_joueurs,
    equipes:      vol.nb_equipes,
    matchs:       vol.nb_matchs,
    performances: vol.nb_perfs,
    classements:  vol.nb_class,
    relations:    vol.nb_rels,
  }
};

// Afficher dans les logs n8n
console.log('=== RAPPORT MONITORING NBA NEO4J ===');
console.log(JSON.stringify(rapport, null, 2));

return [{ json: rapport }];

const fs = require('fs');
const path = require('path');

const LOG_DIR = process.env.NBA_LOG_DIR || '/data/nba/logs';
if (!fs.existsSync(LOG_DIR)) fs.mkdirSync(LOG_DIR, { recursive: true });

const rapport = $input.first().json;
const date = new Date().toISOString().slice(0, 10);
const fname = path.join(LOG_DIR, `monitoring_${date}.json`);

fs.writeFileSync(fname, JSON.stringify(rapport, null, 2));
console.log(`Rapport sauvegardé : ${fname}`);

// Garder uniquement les 30 derniers jours
const files = fs.readdirSync(LOG_DIR)
  .filter(f => f.startsWith('monitoring_'))
  .sort();
if (files.length > 30) {
  files.slice(0, files.length - 30).forEach(f => {
    fs.unlinkSync(path.join(LOG_DIR, f));
  });
}

return [{ json: { ...rapport, rapport_path: fname } }];
